payload.template:
// A round-robin arbiter.

module rr_arbiter #(
    parameter int N = 4            // at least 2
) (
    input  logic         clk,
    input  logic         rst_n,    // synchronous, active low
    input  logic [N-1:0] req,      // one bit per requester
    output logic [N-1:0] grant,    // one-hot, or all zero
    output logic         valid     // high exactly when a grant is made
);

    // your code here.
    //
    // One register: which index was granted most recently. `grant` and
    // `valid` are combinational functions of it and of `req`, so a
    // requester is granted in the cycle it asks rather than the cycle
    // after.
    //
    // The search runs over the N positions AFTER the last one granted,
    // wrapping round, and stops at the first requester it finds. Reset
    // it so that index 0 has top priority on the first cycle.

    assign grant = '0;
    assign valid = 1'b0;

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench. Submit uses another one, which checks the
// rotation over a longer run and that nobody is starved.
module tb;

  localparam int N = 4;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic [N-1:0] req = '0;
  logic [N-1:0] grant;
  logic valid;

  rr_arbiter #(.N(N)) dut (
    .clk(clk), .rst_n(rst_n), .req(req), .grant(grant), .valid(valid)
  );

  integer i;

  // Present a request pattern for one cycle and return just after the
  // rising edge, with `grant` still showing that cycle's decision.
  task ask(input [N-1:0] r);
    begin
      @(negedge clk); req = r;
      #1;
    end
  endtask

  // Let the edge happen, so the arbiter's pointer moves on.
  task settle;
    begin
      @(posedge clk); #1;
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; req = '0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  function automatic integer onehot_index(input [N-1:0] g);
    integer k, c, idx;
    begin
      c = 0; idx = -1;
      for (k = 0; k < N; k = k + 1) if (g[k]) begin c = c + 1; idx = k; end
      onehot_index = (c == 1) ? idx : -1;
    end
  endfunction

  integer g0, g1, g2;
  logic v_idle;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();

    // Nobody asking.
    ask(4'b0000);
    v_idle = valid;
    settle();

    // Everybody asking: 0 first, then 1, then 2.
    ask(4'b1111); g0 = onehot_index(grant); settle();
    ask(4'b1111); g1 = onehot_index(grant); settle();
    ask(4'b1111); g2 = onehot_index(grant); settle();

    $display("CHECK quiet_when_no_requests 0 %0d AT %0d", v_idle, $time);
    $display("CHECK first_grant_is_zero 0 %0d AT %0d", g0, $time);
    $display("CHECK then_one 1 %0d AT %0d", g1, $time);
    $display("CHECK then_two 2 %0d AT %0d", g2, $time);
    $display("DONE 4");
    $finish;
  end

endmodule
